"""code that helps to lead one through opening and accessing the organized latents that I've generated. """from typing import Dictfrom pathlib import Pathimport polars as pl from core.utils.read_parquets import read_parquet_files_into_dictimport osimport globimport numpy as np# 1. we will start with pulling the latents that we're used to working with (from thesis): latent_dir = Path('/Users/vincentcalia-bogan/Desktop/1BRANDEIS MAJOR STUFF/Katz lab/'                  'Senior thesis work/Blech_intra_state_dynamics/output/intermediate_data/RNN_PROCESSING_PARQUETS/')# the raw rnn output: raw_out =  latent_dir / 'raw_output_unwarped'# latents that have had the PCA done to them: pca_out = latent_dir / 'robust_pca_95_unwarped'# you can read these out in any number of ways-- for example: def sweep_parquets(data_dir: Path) -> None:    """Print all .parquet files found in data_dir, with basic shape info."""    files = sorted(data_dir.glob('*.parquet'))    for file in files:        # Load just the schema + row count without pulling all data into memory        df = pl.read_parquet(file)        print(f"  {file.name:50s}  shape={df.shape}  columns={df.columns}")sweep_parquets(raw_out)# should you wish to load one single file directly: df = pl.read_parquet(raw_out / 'AM11_4Tastes_191030_114043_rnn_latent_raw_output_unwarped.parquet')# which will net you the file # using the read_parquet_files_into_dict method that I made so many moons ago, we have: raw_data: Dict[str, pl.DataFrame] = read_parquet_files_into_dict(raw_out)pca_data: Dict[str, pl.DataFrame] = read_parquet_files_into_dict(pca_out)print(f"\nLoaded {len(raw_data)} raw file(s):  {list(raw_data.keys())}")print(f"Loaded {len(pca_data)} pca file(s):  {list(pca_data.keys())}")for name, df in raw_data.items():    print(f"\n── {name} ──")    print(f"  Shape      : {df.shape}")    print(f"  Columns    : {df.columns}")    print(f"  Dtypes     : {df.dtypes}")    print(f"  First row  :\n{df.head(1)}")## NOW PULLING WHATEVER YOU WANT (via trial, taste, changepoint)# Filter to a single trial / taste / (optional) changepointLATENT_COLS = [f'latent_dim_{i}' for i in range(1, 9)]  # adjust range if dims change-- hardcoded but easydef get_trial_slice(    df: pl.DataFrame,    trial: int,    taste: str,    changepoint: int | None = None,) -> pl.DataFrame:    """    Filter df to a single trial + taste (+ optional changepoint),    returning time-ordered latent dim columns.    Parameters    ----------    df          : full Polars DataFrame loaded from one parquet file    trial       : trial ID to select    taste       : taste label to select    changepoint : if provided, further filters to this changepoint value    Returns    -------    Polars DataFrame with columns: ['time', *LATENT_COLS]    sorted ascending by time.    """    mask = (pl.col('trial') == trial) & (pl.col('taste') == taste)    if changepoint is not None:        mask = mask & (pl.col('changepoint') == changepoint)    return (        df.filter(mask)          .select(['time', *LATENT_COLS])          .sort('time')    )# Now extract each latent dim as an explicit numpy vector, just bc we can def extract_latent_vectors(trial_df: pl.DataFrame) -> dict:    """    From a trial-slice DataFrame, pull each latent dim (and time)    into a plain numpy array.    Returns    -------    dict with keys 'time', 'latent_dim_1', ..., 'latent_dim_N'    """    vectors = {'time': trial_df['time'].to_numpy()}    for col in LATENT_COLS:        vectors[col] = trial_df[col].to_numpy()    return vectorsexample_key = list(raw_data.keys())[0]df = raw_data[example_key]# Peek at what values are availableprint("Trials      :", df['trial'].unique().sort().to_list())print("Tastes      :", df['taste'].unique().sort().to_list())print("Changepoints:", df['changepoint'].unique().sort().to_list())# Pull a slice — no changepoint filter# note: tastes are numeric, but:     # "0": "NaCl",    #"1": "Sucrose",    #"2": "Citric Acid",    #"3": "Quinine",trial_df = get_trial_slice(df, trial=0, taste=2)print(f"\nSlice shape: {trial_df.shape}")print(trial_df.head()) # note that .head only gets the top 10 rows of the df by default# Pull the same slice but pinned to a specific changepointtrial_df_cp = get_trial_slice(df, trial=0, taste=2, changepoint=0)# Unpack into explicit vectorsvecs = extract_latent_vectors(trial_df)time        = vecs['time']           # shape (T,)latent_dim1 = vecs['latent_dim_1']   # shape (T,)latent_dim2 = vecs['latent_dim_2']# ... or loop:for dim, arr in vecs.items():    print(f"  {dim:15s}: shape={arr.shape}, dtype={arr.dtype}")# a note on polars <-> pandas: """- Polars uses Arrow-backed memory; .to_pandas() is a zero-copy conversion  where possible (numeric columns), and a copy otherwise.- Pass use_pyarrow_extension_types=True if you want to keep Arrow dtypes  in pandas (requires pandas >= 1.5 + pyarrow).That stated, this can be done via a simple polars method:     df.to_pandas()"""